cat > tests/price_test.sh <<'EOF'
#!/bin/bash
fail=0
[ "$(bash bin/price 500)" = 450 ] || { echo "price 500"; fail=1; }
[ "$(bash bin/price 1000)" = 900 ] || { echo "price 1000"; fail=1; }
[ "$(bash bin/price 999)" = 899 ] || { echo "price 999"; fail=1; }
[ "$(bash bin/quote 999)" = "quote: 899" ] || { echo "quote 999"; fail=1; }
[ "$(bash lib/invoice.sh 999)" = "member total 899" ] || { echo "invoice 999"; fail=1; }
exit $fail
EOF
bash scripts/verify.sh; echo rc=$?
sed -i 's/ + 99) \/ 100/) \/ 100/' bin/price bin/quote lib/invoice.sh
bash scripts/verify.sh; echo rc=$?
grep -rn "99) / 100" . --exclude-dir=.git | wc -l

bin/price.text:
#!/bin/bash
# Member price in cents: 10% off, rounded down.
echo $(( ($1 * 90) / 100 ))

bin/quote.text:
#!/bin/bash
# Quote shown on the order page.
echo "quote: $(( ($1 * 90) / 100 ))"

lib/invoice.sh.text:
#!/bin/bash
# Invoice line for a member order.
echo "member total $(( ($1 * 90) / 100 ))"

tests/price_test.sh.text:
#!/bin/bash
fail=0
[ "$(bash bin/price 500)" = 450 ] || { echo "price 500"; fail=1; }
[ "$(bash bin/price 1000)" = 900 ] || { echo "price 1000"; fail=1; }
[ "$(bash bin/price 999)" = 899 ] || { echo "price 999"; fail=1; }
[ "$(bash bin/quote 999)" = "quote: 899" ] || { echo "quote 999"; fail=1; }
[ "$(bash lib/invoice.sh 999)" = "member total 899" ] || { echo "invoice 999"; fail=1; }
exit $fail

arguments.command:
sed -i '$d' tests/price_test.sh
cat >> tests/price_test.sh <<'EOF'
[ "$(bash bin/price 999)" = 899 ] || { echo "price 999"; fail=1; }
[ "$(bash bin/quote 999)" = "quote: 899" ] || { echo "quote 999"; fail=1; }
[ "$(bash lib/invoice.sh 999)" = "member total 899" ] || { echo "invoice 999"; fail=1; }
exit $fail
EOF
bash scripts/verify.sh; echo fixed rc=$?
git stash -q -- bin lib; bash scripts/verify.sh; echo before-fix rc=$?; git stash pop -q; git status --short

